script.setup:
const s=ctx.state,gl=ctx.gl;
s.program=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,"#version 300 es
precision highp float;
#define GLSLIFY 1
in vec2 v_uv;out vec4 outColor;uniform vec2 u_resolution;uniform sampler2D u_image;
uniform int u_mode;
uniform float u_opacity;
vec3 blendMultiply(vec3 base, vec3 blend) {
	return base*blend;
}

vec3 blendMultiply(vec3 base, vec3 blend, float opacity) {
	return (blendMultiply(base, blend) * opacity + base * (1.0 - opacity));
}

float blendScreen(float base, float blend) {
	return 1.0-((1.0-base)*(1.0-blend));
}

vec3 blendScreen(vec3 base, vec3 blend) {
	return vec3(blendScreen(base.r,blend.r),blendScreen(base.g,blend.g),blendScreen(base.b,blend.b));
}

vec3 blendScreen(vec3 base, vec3 blend, float opacity) {
	return (blendScreen(base, blend) * opacity + base * (1.0 - opacity));
}

float blendOverlay(float base, float blend) {
	return base<0.5?(2.0*base*blend):(1.0-2.0*(1.0-base)*(1.0-blend));
}

vec3 blendOverlay(vec3 base, vec3 blend) {
	return vec3(blendOverlay(base.r,blend.r),blendOverlay(base.g,blend.g),blendOverlay(base.b,blend.b));
}

vec3 blendOverlay(vec3 base, vec3 blend, float opacity) {
	return (blendOverlay(base, blend) * opacity + base * (1.0 - opacity));
}

vec3 blendDifference(vec3 base, vec3 blend) {
	return abs(base-blend);
}

vec3 blendDifference(vec3 base, vec3 blend, float opacity) {
	return (blendDifference(base, blend) * opacity + base * (1.0 - opacity));
}

void main(){vec2 uv=v_uv,p=(uv*2.-1.)*u_resolution/min(u_resolution.x,u_resolution.y);vec3 color;vec3 a=vec3(uv,.3),b=mix(vec3(.2,.7,.9),vec3(.95,.3,.2),.5+.5*sin(uv.y*16.+uv.x*7.));vec3 c=u_mode==0?blendMultiply(a,b):u_mode==1?blendScreen(a,b):u_mode==2?blendOverlay(a,b):blendDifference(a,b);color=mix(a,c,u_opacity);
outColor=vec4(color,1);}");
